-- Shay-to-Aryx bridge tables for workspace, datasource, and chat mapping.
-- Oracle ADB 23ai version of Postgres migrations 0033_shay_skin.sql (bridge tables)
-- and 0034_shay_workspace_map_constraints.sql.
--
-- Type mappings from Postgres:
--   UUID        → VARCHAR2(36)
--   BIGINT      → NUMBER(19)
--   BIGSERIAL   → NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY
--   JSONB       → CLOB  (DEFAULT '{}' / DEFAULT '[]')
--   TIMESTAMPTZ → TIMESTAMP WITH TIME ZONE
--   NOW()       → SYSTIMESTAMP
--
-- Cross-service FKs to gg_workspace (owned by shay-api) are intentionally OMITTED.
-- Adding them caused ORA-02291: the api service inserts bridge rows via an HTTP call
-- from shay-api, but shay-api's SQLAlchemy async session may not have committed the
-- gg_workspace row yet, making the parent key invisible to the api's Oracle connection.
-- Data integrity across service boundaries is enforced at the application layer.
-- The DROP blocks below clean up constraints added by earlier migration runs.

-- ── aryx_shay_workspace_map ───────────────────────────────────────────────────
BEGIN
  EXECUTE IMMEDIATE 'CREATE TABLE aryx_shay_workspace_map (
    shay_workspace_id   VARCHAR2(36)              NOT NULL,
    aryx_workspace_id   NUMBER(19)                NOT NULL,
    company_id          VARCHAR2(36),
    sync_state          CLOB                      DEFAULT ''{}'' NOT NULL,
    created_at          TIMESTAMP WITH TIME ZONE  DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at          TIMESTAMP WITH TIME ZONE  DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_aryx_shay_workspace_map     PRIMARY KEY (shay_workspace_id),
    CONSTRAINT uq_aryx_shay_workspace_aryx_id UNIQUE      (aryx_workspace_id),
    CONSTRAINT fk_aryx_shay_wmap_aryx_ws
        FOREIGN KEY (aryx_workspace_id) REFERENCES aryx_workspace(id) ON DELETE CASCADE
  )';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- Drop cross-service FK to gg_workspace if it was added by a prior migration run.
-- ORA-02443 = constraint does not exist, ORA-00942 = table not found — both safe to skip.
BEGIN
  EXECUTE IMMEDIATE 'ALTER TABLE aryx_shay_workspace_map DROP CONSTRAINT fk_aryx_shay_wmap_gg_ws';
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE NOT IN (-2443, -942) THEN RAISE; END IF;
END;
/

-- ── aryx_shay_datasource_map ──────────────────────────────────────────────────
BEGIN
  EXECUTE IMMEDIATE 'CREATE TABLE aryx_shay_datasource_map (
    shay_datasource_id  VARCHAR2(36)              NOT NULL,
    aryx_datasource_id  NUMBER(19)                NOT NULL,
    shay_workspace_id   VARCHAR2(36)              NOT NULL,
    aryx_workspace_id   NUMBER(19)                NOT NULL,
    ingest_job_id       VARCHAR2(500),
    created_at          TIMESTAMP WITH TIME ZONE  DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at          TIMESTAMP WITH TIME ZONE  DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_aryx_shay_datasource_map  PRIMARY KEY (shay_datasource_id),
    CONSTRAINT uq_aryx_shay_ds_aryx_id      UNIQUE      (aryx_datasource_id),
    CONSTRAINT fk_aryx_shay_dsmap_aryx_ds
        FOREIGN KEY (aryx_datasource_id) REFERENCES aryx_datasource(id) ON DELETE CASCADE,
    CONSTRAINT fk_aryx_shay_dsmap_aryx_ws
        FOREIGN KEY (aryx_workspace_id)  REFERENCES aryx_workspace(id)  ON DELETE CASCADE
  )';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- Drop cross-service FK to gg_workspace if it was added by a prior migration run.
BEGIN
  EXECUTE IMMEDIATE 'ALTER TABLE aryx_shay_datasource_map DROP CONSTRAINT fk_aryx_shay_dsmap_gg_ws';
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE NOT IN (-2443, -942) THEN RAISE; END IF;
END;
/

BEGIN
  EXECUTE IMMEDIATE 'CREATE INDEX idx_aryx_shay_datasource_map_workspace
    ON aryx_shay_datasource_map (shay_workspace_id, aryx_workspace_id)';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -1408 THEN NULL; END IF;
END;
/

-- ── aryx_shay_chat_map ────────────────────────────────────────────────────────
BEGIN
  EXECUTE IMMEDIATE 'CREATE TABLE aryx_shay_chat_map (
    shay_thread_id      VARCHAR2(36)              NOT NULL,
    aryx_workspace_id   NUMBER(19)                NOT NULL,
    shay_workspace_id   VARCHAR2(36)              NOT NULL,
    ask_session_key     VARCHAR2(500)             NOT NULL,
    created_at          TIMESTAMP WITH TIME ZONE  DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at          TIMESTAMP WITH TIME ZONE  DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_aryx_shay_chat_map PRIMARY KEY (shay_thread_id),
    CONSTRAINT fk_aryx_shay_cmap_aryx_ws
        FOREIGN KEY (aryx_workspace_id) REFERENCES aryx_workspace(id) ON DELETE CASCADE
  )';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- Drop cross-service FK to gg_workspace if it was added by a prior migration run.
BEGIN
  EXECUTE IMMEDIATE 'ALTER TABLE aryx_shay_chat_map DROP CONSTRAINT fk_aryx_shay_cmap_gg_ws';
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE NOT IN (-2443, -942) THEN RAISE; END IF;
END;
/

-- ── aryx_shay_chat_turn ───────────────────────────────────────────────────────
BEGIN
  EXECUTE IMMEDIATE 'CREATE TABLE aryx_shay_chat_turn (
    id                  NUMBER(19)                GENERATED BY DEFAULT ON NULL AS IDENTITY,
    shay_thread_id      VARCHAR2(36)              NOT NULL,
    aryx_workspace_id   NUMBER(19)                NOT NULL,
    question            CLOB                      NOT NULL,
    answer              CLOB                      NOT NULL,
    citations           CLOB                      DEFAULT ''[]'' NOT NULL,
    usage               CLOB                      DEFAULT ''{}'' NOT NULL,
    grounding           CLOB                      DEFAULT ''{}'' NOT NULL,
    created_at          TIMESTAMP WITH TIME ZONE  DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_aryx_shay_chat_turn PRIMARY KEY (id),
    CONSTRAINT fk_aryx_shay_cturn_thread
        FOREIGN KEY (shay_thread_id)    REFERENCES aryx_shay_chat_map(shay_thread_id) ON DELETE CASCADE,
    CONSTRAINT fk_aryx_shay_cturn_aryx_ws
        FOREIGN KEY (aryx_workspace_id) REFERENCES aryx_workspace(id)                ON DELETE CASCADE
  )';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

BEGIN
  EXECUTE IMMEDIATE 'CREATE INDEX idx_aryx_shay_chat_turn_thread
    ON aryx_shay_chat_turn (shay_thread_id, created_at)';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -1408 THEN NULL; END IF;
END;
/
